package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Actual obstructed coin dialogs, holdout pixels and the shipped runtime input guards. */
public final class Video6682ReplayTest {
 static final String P=CoinPreset.P;static int checks;static Map<String,float[]> refs;
 static final Map<String,VirtualPresetProfileTest.Image> images=new LinkedHashMap<>();
 static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static void load()throws Exception{
  refs=VirtualPresetProfileTest.canonical("tests/video6682-references.bin");
  try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/video6682-replay.bin.gz")))){int count=in.readInt(),nativeCount=0;for(int i=0;i<count;i++){String id=in.readUTF();VirtualPresetProfileTest.Image image=new VirtualPresetProfileTest.Image(in);images.put(id,image);if(image.width==1080&&image.height==2424)nativeCount++;}check(count==45&&nativeCount==6&&in.read()==-1,"complete held-out video fixture with six native frames");}
 }
 static final class Run {
  final PhaseEngine e=new PhaseEngine();final CoinLayout layout;Map<String,float[]> last;
  Run(){CoinPreset.install(e,refs);e.strictRuntime=true;layout=CoinLayout.install(e,refs);AdCloseAutomaton.install(e,CoinPreset.APP);check(layout!=null&&e.validate().isEmpty(),"complete runtime graph");}
  Map<String,float[]> sample(String id,long now){VirtualPresetProfileTest.Image im=images.get(id);last=layout.sampleRelative(e.activeRegions(),im.width,im.height,im,now);return last;}
  PhaseEngine.Watch event(String state,String first,String second){e.enter(P+state,0);e.observe(sample(first,1000),1000);check(e.poll()==null,"one frame cannot commit "+state+" / "+first);e.observe(sample(second,1350),1350);return e.poll();}
  PhaseEngine.Watch expect(String state,String first,String second,String next,int action){PhaseEngine.Watch w=event(state,first,second);check(w!=null&&w.action==action&&w.nextPhase.equals(P+next),"coin branch "+state+" / "+first+" -> "+next+" / "+(w==null?e.diagnostic:w.id));return w;}
  float[] point(PhaseEngine.Watch w,String id){VirtualPresetProfileTest.Image im=images.get(id);return layout.pointRelative(w,last,im.width,im.height);}
 }
 static void scenes(){
  for(String state:new String[]{"main","check","verify"})for(String[] row:new String[][]{{"4","14-native","bonus"},{"6","18","bonus"},{"14","16","bonus"},{"24","24-native","missions"},{"40.5","41","missions"},{"38.5","38.5-native","reward"},{"38.5","39","reward"},{"49.5","50.3-native","boost-pocket"}}){Run r=new Run();r.expect(state,row[0],row[1],row[2],PhaseEngine.WAIT);check(!CoinPreset.playable(r.e,r.last),"covered or other scene holds marker input immediately");}
  for(String id:new String[]{"20.5","21","22","42","44-native","46","48","49"}){Run r=new Run();PhaseEngine.Watch w=r.expect("verify",id,id,"main",PhaseEngine.WAIT);r.e.finish(w,1400);check(CoinPreset.playable(r.e,r.last),"confirmed actual home resumes main markers: "+id);float[] p=r.layout.mainPointRelative(r.last,images.get(id).width,images.get(id).height);check(p!=null&&Math.abs(p[0]/images.get(id).width-.5f)<.02f&&p[1]/images.get(id).height>.77f&&p[1]/images.get(id).height<.84f,"main point lies in the actual rabbit coin button");}
 }
 static void controls(){
  Run noAd=new Run();PhaseEngine.Watch dismissal=noAd.expect("boost-pocket","50.3-native","50.3-native","optional-cancel-wait",PhaseEngine.BACK);check(noAd.point(dismissal,"50.3-native")==null,"no cancel text means Back, never a guessed CM point");
  for(String[] row:new String[][]{{"bonus","14-native","verify",".774",".797"},{"reward","38.5-native","mission-opening",".551",".584"}}){Run r=new Run();PhaseEngine.Watch w=r.expect(row[0],row[1],row[1],row[2],PhaseEngine.CENTER);VirtualPresetProfileTest.Image im=images.get(row[1]);check(r.last.get(w.regionId).length==1&&r.last.get(w.regionId)[0]==1,"new independent landmarks prove an otherwise obstructed control");float[] p=r.point(w,row[1]);check(p!=null&&p[0]/im.width>.3f&&p[0]/im.width<.7f&&p[1]/im.height>Float.parseFloat(row[3])&&p[1]/im.height<Float.parseFloat(row[4]),"input uses this dialog's actual control, outside CM/install alternatives: "+Arrays.toString(p));Map<String,float[]> fresh=r.sample(row[1],1800);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"native preflight rechecks both visible landmarks");fresh=r.sample("10",2000);check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh)&&r.layout.pointRelative(w,fresh,im.width,im.height)==null,"a newly shown ad cancels the pending tap and point");check(r.e.cancelIfCurrent(w,r.e.current,r.e.epoch)&&r.e.current.equals(P+row[0]),"cancelled input does not finish the transition");}
  Run r=new Run();PhaseEngine.Watch w=r.expect("bonus","14","16","verify",PhaseEngine.CENTER);r.e.finish(w,1400);check(!CoinPreset.playable(r.e,r.last),"start input alone never enables coin dropping");w=r.expect("verify","21","22","main",PhaseEngine.WAIT);r.e.finish(w,1400);check(CoinPreset.playable(r.e,r.last),"actual returned home enables coin dropping");
  r=new Run();w=r.expect("missions","24","24-native","claim-wait",PhaseEngine.CENTER);float[] p=r.point(w,"24-native");check(w.id.equals(P+"get-tap")&&p!=null&&p[0]/1080>.72f&&p[0]/1080<.88f&&p[1]/2424>.395f&&p[1]/2424<.435f,"actual first orange Get precedes yellow Play");List<PhaseEngine.Region> plan=ScanPlan.select(r.e,w.regionId,false);VirtualPresetProfileTest.Image im=images.get("24-native");Map<String,float[]> fresh=r.layout.sampleRelative(plan,im.width,im.height,im,1700);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"Get preflight preserves mission heading dependency");
  r=new Run();w=r.expect("missions","40","41","mission-verify",PhaseEngine.CENTER);p=r.point(w,"41");check(w.id.equals(P+"mission-play")&&p!=null&&p[1]/images.get("41").height>.395f&&p[1]/images.get("41").height<.435f,"no unclaimed Get allows the visible first Play");
 }
 static void negatives(){
  for(String key:new String[]{"bonus","reward"}){String id=key.equals("bonus")?"14-native":key.equals("reward")?"38.5-native":"50.3-native";VirtualPresetProfileTest.Image im=images.get(id);
   for(int part=0;part<3;part++){Run r=new Run();r.e.enter(P+key,0);final int mode=part;int[] cut=RegionMath.bounds(CoinControlEvidence.anchors(key)[Math.min(part,1)],im.width,im.height);RegionSampler.Pixels changed=(x,y)->{int c=im.get(x,y);if(mode==2)return 0xff000000|((c>>16&255)/2)<<16|((c>>8&255)/2)<<8|(c&255)/2;return x>=cut[0]-2&&x<cut[2]+2&&y>=cut[1]-2&&y<cut[3]+2?0xff404040:c;};Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),im.width,im.height,changed,1000);PhaseEngine.Watch w=r.e.rule(P+(key.equals("bonus")?"start-tap":key.equals("reward")?"reward-close":"boost-pocket-cm"));check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,s),"missing dialog body, missing own label or dim display blocks action: "+key+" / "+part);check(r.layout.pointRelative(w,s,im.width,im.height)==null,"unconfirmed dialog supplies no guessed point");}
  }
  for(String id:new String[]{"8","10","13.2","26","30","37.3","51","52.5","54"}){Run r=new Run();PhaseEngine.Watch w=r.event("check",id,id);check(w==null||AdCloseAutomaton.handles(w.regionId),"ad/browser/loading/system UI is never a game action: "+id);check(!CoinPreset.playable(r.e,r.last)&&!r.last.containsKey(AdaptiveLayout.MAIN),"foreign or dim scene cannot supply a main marker point");}
 }
 static void advertisements(){
  for(String state:new String[]{"ad","reward-ad","mission-ad"})for(String id:new String[]{"12.5","32-native","34","36"}){Run r=new Run();String next=state;PhaseEngine.Watch w=r.expect(state,id,id,next,PhaseEngine.CENTER);float[] p=r.point(w,id);VirtualPresetProfileTest.Image im=images.get(id);check(w.regionId.equals(AdCloseAutomaton.RIGHT)&&p!=null&&p[0]/im.width>.91f&&p[0]/im.width<.97f&&p[1]/im.height>.08f&&p[1]/im.height<.12f,"ready triangle-and-bar uses observed disk centre including black top margin");}
  for(String id:new String[]{"8","10","26","30","51","52.5"}){Run r=new Run();check(r.event("reward-ad",id,id)==null,"playing/counting/loading ad exposes no ready next: "+id);}
  VirtualPresetProfileTest.Image im=images.get("32-native");int cx=1017,cy=236,radius=32;
  for(int kind=0;kind<2;kind++){final int mode=kind;RegionSampler.Pixels empty=(x,y)->(x-cx)*(x-cx)+(y-cy)*(y-cy)<=radius*radius?(mode==0?0xffdddddd:0xff333333):im.get(x,y);check(AdReadyNextDetector.find(im.width,im.height,new float[]{.87f,0,1,.14f},empty,new Run().layout.readyNext)==null,"empty circle or absent disk is not a ready skip symbol");}
  RegionSampler.Pixels two=(x,y)->{int sy=y+80;return x>=980&&x<1055&&sy>=200&&sy<275?im.get(x,sy):im.get(x,y);};check(AdReadyNextDetector.find(im.width,im.height,new float[]{.87f,0,1,.14f},two,new Run().layout.readyNext)==null,"two ready symbols in one corner are ambiguous");
 }
 static void geometry(){
  for(String key:new String[]{"bonus","reward"}){String id=key.equals("bonus")?"14-native":key.equals("reward")?"38.5-native":"50.3-native";VirtualPresetProfileTest.Image im=images.get(id);
   for(float[] t:new float[][]{{1,1,0,0},{1,.90f,0,.06f},{.94f,.86f,.03f,.08f}}){Run r=new Run();r.e.enter(P+key,0);int width=720,height=1616;RegionSampler.Pixels pixels=(x,y)->{float sx=(x/(float)width-t[2])/t[0],sy=(y/(float)height-t[3])/t[1];return sx<0||sx>=1||sy<0||sy>=1?0xff142030:im.get(Math.min(im.width-1,(int)(sx*im.width)),Math.min(im.height-1,(int)(sy*im.height)));};Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),width,height,pixels,1000);PhaseEngine.Watch w=r.e.rule(P+(key.equals("bonus")?"start-tap":key.equals("reward")?"reward-close":"boost-pocket-cm"));check(r.e.confirmsAction(w,r.e.current,r.e.epoch,s),"dialog recognizes its resized/inset frame: "+key+" / "+Arrays.toString(t));float[] p=r.layout.pointRelative(w,s,width,height);float[] target=AdaptiveLayout.map(CoinControlEvidence.touch(key),t);check(p!=null&&Math.abs(p[0]/width-(target[0]+target[2])/2)<.03f&&Math.abs(p[1]/height-(target[1]+target[3])/2)<.015f,"resized/inset point follows the visible control");}
   Run r=new Run();r.e.enter(P+key,0);int fw=1700,fh=2700,left=300,top=130;RegionSampler.Pixels moved=(x,y)->x>=left&&x<left+im.width&&y>=top&&y<top+im.height?im.get(x-left,y-top):0xff505050;Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),fw,fh,moved,1000,new int[]{left,top,left+im.width,top+im.height});PhaseEngine.Watch w=r.e.rule(P+(key.equals("bonus")?"start-tap":key.equals("reward")?"reward-close":"boost-pocket-cm"));float[] p=r.layout.pointRelative(w,s,fw,fh);float[] b=CoinControlEvidence.touch(key);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,s)&&p!=null&&Math.abs(p[0]-left-im.width*(b[0]+b[2])/2)<3&&Math.abs(p[1]-top-im.height*(b[1]+b[3])/2)<5,"moved app window offsets actual tap coordinates");check(r.layout.pointRelative(w,s,fw+1,fh)==null,"stale frame size invalidates a pending tap");
  }
 }
 static void missionGateAndOwnership(){
  for(String id:new String[]{"21","22","44-native","48"}){Run r=new Run();check(r.event("main",id,id)==null&&CoinPreset.playable(r.e,r.last),"1665/1650 and red badge do not interrupt unfinished coin dropping: "+id);}
  Run r=new Run();PhaseEngine.Watch w=r.expect("clear","14","16","mission-bonus",PhaseEngine.WAIT);r.e.finish(w,1400);w=r.expect("mission-bonus","14","16","mission-opening",PhaseEngine.CENTER);r.e.finish(w,1400);w=r.expect("mission-opening","21","22","mission-tap",PhaseEngine.WAIT);check(!r.e.phases.get(r.e.current).markersDuring,"only an observed stage clear leads into mission collection");
  PhaseEngine old=CoinPreset.previousDefaults(refs),fresh=new PhaseEngine();CoinPreset.install(fresh,refs);check(old.rule(P+"mission-notice")!=null&&CoinPreset.upgrade(old)&&old.rule(P+"mission-notice")==null,"existing standard settings remove the unfinished badge arrow");check(AutomatonGraph.sameConfiguration(old,fresh)&&!CoinPreset.upgrade(old),"migration is complete and idempotent");
  PhaseEngine edited=CoinPreset.previousDefaults(refs);edited.rule(P+"start-tap").action=PhaseEngine.BACK;check(!AutomatonGraph.sameConfiguration(edited,CoinPreset.previousDefaults(refs)),"unedited legacy ownership test does not claim custom actions");edited=fresh.runtimeCopy();edited.regions.get(P+"bonus").bounds[0]+=.01f;CoinLayout custom=CoinLayout.install(edited,refs);check(custom!=null&&!custom.controls.controls.containsKey(P+"bonus"),"custom control coordinates retain their own recognition");edited=fresh.runtimeCopy();edited.rule(P+"start-tap").reference=new float[1536];custom=CoinLayout.install(edited,refs);check(!edited.rule(P+"start-tap").runtimeControlEvidence,"custom recorded image cannot accept a factory proof");
  check(!fresh.rule(P+"start-tap").runtimeControlEvidence&&!fresh.rule(P+"reward-close").runtimeControlEvidence,"runtime evidence never changes persisted definitions");
  edited=fresh.runtimeCopy();edited.rule(P+"start-tap").threshold=.001f;custom=CoinLayout.install(edited,refs);edited.enter(P+"bonus",0);VirtualPresetProfileTest.Image im=images.get("14-native");Map<String,float[]> s=custom.sampleRelative(edited.activeRegions(),im.width,im.height,im,1000);check(!edited.rule(P+"start-tap").runtimeControlEvidence&&s.get(P+"bonus").length!=1&&!edited.confirmsAction(edited.rule(P+"start-tap"),edited.current,edited.epoch,s),"custom tighter tolerance keeps its original comparison and cannot accept a factory proof");
 }
 static void dailyPriority(){
  Run r=new Run();DailyCompletion profile=DailyRouteTest.profile();profile.install(r.e);r.e.enter(P+"missions",0);for(long now:new long[]{1000,1350}){Map<String,float[]> s=r.sample("40",now);s.put(DailyCompletion.REGION,profile.done.clone());s.put(DailyCompletion.HEADING,profile.heading.clone());DailyCompletion.continuation(r.e,s);r.e.observe(s,now);PhaseEngine.Watch w=r.e.poll();if(now==1000)check(w==null,"first all-daily-done frame holds the otherwise visible Play");else check(w!=null&&w.nextPhase.equals(DailyCompletion.PHASE),"two explicit all-daily-done observations outrank game and timers");check(!r.e.confirmsAction(r.e.rule(P+"mission-play"),r.e.current,r.e.epoch,s),"completion blocks Play at input preflight as well");}
 }
 public static void main(String[] args)throws Exception{load();scenes();controls();negatives();advertisements();geometry();missionGateAndOwnership();dailyPriority();System.out.println("Video6682ReplayTest: "+checks+" checks passed; held-out native coin dialogs/controls/ad next, interruptions, relative points, premature mission removal, migration and daily priority; new APK device input not tested");}
}
